            return (typeof github_list_workflow_runs !== 'undefined')
                ? github_list_workflow_runs(args)
                : '{"workflow_runs":[]}';
        },
        file_write: function(writeOpts) {
            if (opts.onFileWrite) opts.onFileWrite(writeOpts);
